import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class WordFileWriterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("wordfile-test", ".txt");
        try {
            List<String> words = List.of("apple", "banana", "cherry");
            WordFileWriter.writeWords(file, words);
            check("file holds one word per line", List.of("apple", "banana", "cherry"), Files.readAllLines(file));
            check("round trip returns the same words", words, WordFileWriter.readWords(file));
            check("round trip size", 3, WordFileWriter.readWords(file).size());
            Files.writeString(file, "dog\ncat\n");
            check("readWords on a file written by the test", List.of("dog", "cat"), WordFileWriter.readWords(file));
            WordFileWriter.writeWords(file, List.of("solo"));
            check("write replaces previous content", List.of("solo"), WordFileWriter.readWords(file));
            WordFileWriter.writeWords(file, List.of());
            check("empty list round trip", List.of(), WordFileWriter.readWords(file));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        } finally {
            Files.deleteIfExists(file);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

